import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { position, rotation, scale } = config.scenePosition || {};
  const { textureLoader } = ctx;
  const { Mesh, PlaneGeometry } = ctx.THREE;

  // Dimensions derived from atlas rect (512x320) – maintain aspect ratio, scale to ~2.0 wide
  const width = 2.0;
  const height = width * (320 / 512); // ≈1.25

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(position?.[0] ?? -3.2, position?.[1] ?? -0.3, position?.[2] ?? 0);
  mesh.rotation.set(rotation?.[0] ?? 0, rotation?.[1] ?? 0, rotation?.[2] ?? 0);
  mesh.scale.set(scale?.[0] ?? 1, scale?.[1] ?? 1, scale?.[2] ?? 1);

  // Load texture asynchronously
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  let loadedTexture = null;
  textureLoader.loadTexture(imageUrl).then((tex) => {
    loadedTexture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  // Attach handlers (none required, but must exist)
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return mesh;
}
